func (r *mutationResolver) TransitionTimesheet(ctx context.Context, input gqlmodel.TransitionTimesheetInput) (*worker.Timesheet, error) {
	sheetID, err := pulid.MustParse(input.ID)
	if err != nil {
		return nil, invalidIDError("id", "Timesheet is invalid")
	}

	authCtx, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	sheet, err := r.timesheetService.GetTimesheet(ctx, &repositories.GetTimesheetByIDRequest{
		ID:         sheetID,
		TenantInfo: tenantInfo(authCtx),
	})
	if err != nil {
		return nil, err
	}

	// Each answer is a different grant: handing a week over is not the same
	// act as signing it off. The worker is read off the sheet rather than
	// taken from the caller: an id supplied alongside the one being acted on
	// is an id somebody can lie about.
	if _, _, err = r.requireTeamScope(
		ctx,
		permission.ResourceTimesheet,
		timesheetPermissionFor(input.Status),
		worker.ApprovalScopeAll,
		sheet.WorkerID,
	); err != nil {
		return nil, err
	}

	return r.timesheetService.Transition(ctx, &timesheetservice.TransitionTimesheetRequest{
		ID:         sheetID,
		Status:     input.Status,
		Note:       stringValue(input.Note),
		TenantInfo: tenantInfo(authCtx),
		UserID:     authCtx.UserID,
	})
}

