func (r *queryResolver) Timesheets(ctx context.Context, filter *gqlmodel.TimesheetFilterInput) ([]*worker.Timesheet, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceTimesheet, permission.OpRead)
	if err != nil {
		return nil, err
	}

	req := &repositories.ListTimesheetsRequest{
		TenantInfo:    tenantInfo(authCtx),
		IncludeWorker: true,
	}
	if filter != nil {
		if req.WorkerID, err = optionalID(filter.WorkerID); err != nil {
			return nil, invalidIDError("workerId", "Worker is invalid")
		}
		req.Statuses = filter.Statuses
		req.From = int64Value(filter.From)
		req.To = int64Value(filter.To)
		req.UnexportedOnly = boolValue(filter.UnexportedOnly)
		req.Limit = intValue(filter.Limit)
		if boolValue(filter.TeamOnly) {
			if req.ManagerIDs, err = r.rotaManagerIDs(
				ctx,
				authCtx.UserID,
				tenantInfo(authCtx),
			); err != nil {
				return nil, err
			}
		}
	}

	return r.timesheetService.ListTimesheets(ctx, req)
}

